contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint ownerBefore = owner.balance;

        bool success;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = true;
        }

        assert(!success || owner.balance >= ownerBefore + amount || owner == address(this));
    }

    receive() external payable {}
}

