        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        uint ownerBefore = owner.balance;
        bool success;
        try c.go{value: amount}() {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(!success || owner.balance >= ownerBefore + amount || owner == address(this));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
